  // TIA/EIA-422(송신기 1·수신기 10·1200 m·200 mV·공통 모드 7 V·먼 끝 종단), TIA-485(1.5 V·32 단위 부하 약 12 kΩ·1/8 UL 256·−7~12 V·200 mV·1200 m·양 끝 종단·반이중/전이중).
