          "자기 프로그램이 보낸 바이트가 맞는지 보려면 웹 도구 «MC 프로토콜(SLMP) 프레임 해석기» 에 붙여 넣습니다. 머리 칸과 명령 데이터를 풀고, 시뮬레이터가 어떤 종료 코드로 답할지도 보여 줍니다.",
