          "«응답 지연(ms)»: 응답을 늦게 보내 시간 초과 설정을 봅니다. «지연 최대» 를 넣으면 요청마다 그 사이에서 아무렇게나 늦춥니다.",
          "«응답 안 함»: 요청은 처리하고(쓰기는 반영) 응답만 보내지 않습니다 — 시간 초과·재시도 처리 시험.",
