    // 근거: data/devices 의 각 인버터 comm.notes(제조사 매뉴얼 쪽 번호 포함) — LS S100·미쓰비시 FR-E800·야스카와 V1000·슈나이더 ATV320·오므론 3G3M1·3G3JX.
